content.text:
        for node in part:
            if node != root and indeg.get(node, 0) != 1:
                return False
        stack = [root]
        visited = {root}
        while stack:
            x = stack.pop()
            for y in adj.get(x, ()):
                if y not in visited:
                    visited.add(y)
                    stack.append(y)
        if visited != part:
            return False
        weight[root] = weight.get(root, 0) + count
        for edge in edges:
            key = (edge[0], edge[1])
            logical[key] = logical.get(key, 0) + count

    for node in part:
        if demands[node] == 0:
            if weight.get(node, 0) != 0:
                return False
        elif weight.get(node, 0) != demands[node]:
            return False

    # --- routes ------------------------------------------------------------
    routed = {}
    for record in routes:
        if not isinstance(record, list) or len(record) != 4:
            return False
        u, v, count, recipe = record
        if not isinstance(u, int) or isinstance(u, bool):
            return False
        if not isinstance(v, int) or isinstance(v, bool):
            return False
        if u not in part or v not in part or u == v:
            return False
        if not isinstance(count, int) or isinstance(count, bool):
            return False
        if count <= 0 or count > total:
            return False
        if not isinstance(recipe, int) or isinstance(recipe, bool):
            return False
        if recipe < 0 or recipe >= len(recipes):
            return False
        walk_end = ends.get(recipe)
        if walk_end is None or walk_end[0] != u or walk_end[1] != v:
            return False
        key = (u, v)
        routed[key] = routed.get(key, 0) + count
    for key, value in logical.items():
        if routed.get(key, 0) != value:
            return False
    for key, value in routed.items():
        if logical.get(key, 0) != value:
            return False

    # --- physical load -----------------------------------------------------
    loads = _plan_loads(plan, links)
    for (link, direction), value in loads.items():
        if value > caps.get(link, 0):
            return False
    return True


def _try_variant(n, links, envelope, period, participants, demands, variant, order=0,
                 lenient=False):
    """Build one concrete plan; returns the plan or ``None``.

    With ``lenient`` the physical walks may pass through participants.  The
    protocol asks for walks that only use ordinary forwarding vertices, but a
    fabric whose participants are not directly adjacent still has to be
    schedulable, so the relaxed walk is used as a last resort.
    """
    part = set(participants)
    ordinary = set(range(n)) - part
    transit = set(range(n)) if lenient else ordinary
    adj = _adjacency(n, links, envelope)
    caps = {link: period * rate for link, rate in envelope.items()}

    # physical reachability between participants
    reach = {}
    for u in participants:
        parent, _order = _bfs_tree(adj, u, transit)
        reach[u] = [w for w in parent if w in part and w != u]

    if variant.startswith("chain"):
        chain = None
        for attempt in range(4):
            chain = _chain_order(part, reach, _RNG, attempt)
            if chain is not None:
                trees, logical = _chain_trees(part, reach, demands, chain)
                if trees is not None:
                    break
        if chain is None or trees is None:
            return None
    else:
        trees, logical = _logical_trees(participants, demands, reach, variant)
    if trees is None:
        return None

    routed = _route(adj, ordinary, caps, logical, order, transit)
    if routed is None:
        return None

    recipes, route_ids = _recipes_for(routed)
    if recipes is None:
        return None

    route_records = []
    for (u, v, count, _chain), node in zip(routed, route_ids):
        route_records.append([u, v, count, node])

    tree_records = []
    for root in sorted(trees):
        parent = trees[root]
        edges = []
        for node, prev in sorted(parent.items()):
            if node != root:
                edges.append([prev, node])
        tree_records.append([root, demands[root], edges])

    plan = {"trees": tree_records, "routes": route_records, "recipes": recipes}
    if not validate_plan(plan, n, links, caps, participants, demands, period,
                         strict=not lenient):
        return None
    return plan


def compile_plan(n, links, envelope, period, participants, demands):
    """Compile a proposal.

    Returns ``(plan, cut)``.  ``plan`` is a valid plan when the proposal is
    admissible, otherwise ``None`` and ``cut`` holds the vertices of a
    deficient cut witness (best effort when the witness cannot be made
    strictly deficient).
    """
    caps = {link: period * rate for link, rate in envelope.items()}
    cut, _deficit = find_deficient_cut(n, links, caps, participants, demands)
    if cut is not None:
        return None, cut
